from dataclasses import dataclass

@dataclass(frozen=True)
class Witness:
    name: str
    rank: int
    true: bool = True
    provable: bool = False
    negation_provable: bool = False

def ranked_prefix(n: int) -> list[Witness]:
    if n < 0: raise ValueError("n must be nonnegative")
    return [Witness(f"G_{k}", k) for k in range(n)]

if __name__ == "__main__":
    for w in ranked_prefix(10): print(w)

def liar_table() -> list[tuple[bool, bool, bool]]:
    return [(p, not p, p == (not p)) for p in (False, True)]

if __name__ == "__main__":
    print("truth, untruth, equivalent")
    for row in liar_table(): print(row)

from dataclasses import dataclass

@dataclass(frozen=True)
class Witness:
    level: str
    sentence: str
    true: bool = True
    provable: bool = False

def two_level_cycle() -> list[Witness]:
    return [Witness("Lower", "G_lower"), Witness("Upper", "I(G_lower)"),
            Witness("Upper", "G_upper"), Witness("Lower", "J(G_upper)")]

if __name__ == "__main__":
    for w in two_level_cycle(): print(w)

